def create_default(field: FieldInfo) -> str:
    """Create the default value for pydantic ModelFields."""
    # Determine if field is required
    is_required = getattr(field, "is_required", False)
    if "=" not in repr(field) and not is_required:
        default = ""
    if "=" not in repr(field) and is_required:
        default = ""
    elif not is_required:
        default = f'="{field.default}"'
    elif field.default is None and not is_required:
        default = "=None"
    elif field.default is not None:
        default = f'="{field.default}"'
    else:
        default = ""

    return default


def create_default_typer(
    panel_name: str,
    field: FieldInfo,
    *,
    prompt_always: bool = False,
) -> str:
    """Create the default value for pydantic ModelFields for typer functions."""
    prompt = ""
    if prompt_always:
        prompt = ", prompt=True"
    is_required = getattr(field, "is_required", False)
    if "=" not in repr(field) and not is_required:
        default = ""
    if "=" not in repr(field) and is_required:
        default = "=None"
    elif not is_required:
        default = f'="{field.default}"'
    elif field.default is None and not is_required:
        default = f' = typer.Option(None, help="{field.description or ""}", rich_help_panel="{panel_name}"{prompt})'
    elif field.default is not None:
        default = f' = typer.Option("{field.default}", help="{field.description or ""}", rich_help_panel="{panel_name}"{prompt})'
    else:
        default = f' = typer.Option(..., help="{field.description or ""}", rich_help_panel="{panel_name}", prompt=True)'
    return default

